CREATE DATABASE IF NOT EXISTS neon_plan CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE neon_plan;

CREATE TABLE events (
    id INT AUTO_INCREMENT PRIMARY KEY,
    date_label VARCHAR(50) NOT NULL COMMENT 'Дата (напр. 07.09 пн)',
    time_range VARCHAR(100) NOT NULL COMMENT 'Время проведения',
    location VARCHAR(255) NOT NULL COMMENT 'Место проведения',
    title VARCHAR(255) NOT NULL COMMENT 'Название мероприятия',
    description TEXT COMMENT 'Описание мероприятия',
    coverage VARCHAR(100) COMMENT 'Примерный охват',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

